B.bSF=new A.x("\ub178\ud2b8\ub294 \ub85c\uceec \uc800\uc7a5\ud558\uace0, \ud0c0\uc774\uba38\xb7\uc9d1\uc911 \ubaa8\ub4dc\ub294 \ud604\uc7ac \uae30\uae30\uc5d0\uc11c \ub3d9\uc791\ud569\ub2c8\ub2e4. AI \ud29c\ud130\ub294 /serverchat/config\uc640 /serverchat/message\ub97c \uc0ac\uc6a9\ud569\ub2c8\ub2e4.",null,B.ah3,null,null,null,null,null,null,null,null)
